import json, numpy as np
from scipy.linalg import eigh
from scipy.optimize import minimize_scalar
D=8; N=3; occ=(2,3,4); pos=np.arange(D)-3.5
basis=[tuple(i for i in range(D) if mask>>i&1) for mask in range(1<<D) if mask.bit_count()==N]
idx={s:i for i,s in enumerate(basis)}
def hp(J,tr,ti):
 H=np.zeros((len(basis),len(basis)),complex)
 for a,s in enumerate(basis):
  H[a,a]=sum(tr*pos[i]**2+ti*pos[i] for i in s)
  for j in range(D-1):
   if j in s and j+1 not in s:
    t=list(s); t.remove(j); t.append(j+1); t.sort(); b=idx[tuple(t)]
    H[a,b]=H[b,a]=-J
 return H
def calc(e,J):
 H=hp(J,e.get('trap',0),e.get('tilt',0)); en,v=eigh(H); state=v@((v[idx[occ],:].conj())*np.exp(-1j*en*e['duration'])) # wait coefficients v† initial = conj(row)
 # exact boson corr Cij = <b_i† b_j>
 C=np.zeros((D,D),complex)
 for a,s in enumerate(basis):
  for j in s:
   sj=list(s); sj.remove(j)
   for i in range(D):
    if i in sj: continue
    ss=sorted(sj+[i]); b=idx[tuple(ss)]
    # matrix b_i^dag b_j maps s to ss with no signs
    C[i,j]+=state[b].conj()*state[a]
 if e['observable']=='density': return C[e['site'],e['site']].real
 k=e['wave_number']; mode=np.exp(-1j*k*pos)
 return np.vdot(mode,C@mode).real/D
Dta=json.load(open('data/calibration.json'))
def res(J): return np.array([(calc(x['input'],J)-x['value'])/x['sigma'] for x in Dta])
for J in [.8,.9,1,1.1,1.2]: print(J,np.sqrt(np.mean(res(J)**2)), np.max(abs(res(J))))
fit=minimize_scalar(lambda j: np.sum(res(j)**2),bounds=(.8,1.2),method='bounded',options={'xatol':1e-14})
print(fit.x, np.sqrt(np.mean(res(fit.x)**2)),np.max(abs(res(fit.x))))
print('mom',sum(x['input']['observable']=='momentum' for x in Dta))
